## 🧠 3. `script.js` (Lógica em JavaScript)

Este é o coração do projeto. Ele lida com a troca de painéis, cálculos, validações e interações.

```javascript
$(document).ready(function() {
    // Variáveis de Estado
    let valorBase = 0;
    let metodoAtual = 'pix';

    // Elementos DOM
    const $valorInput = $('#valor');
    const $informarDadosBtn = $('#informarDados');
    const $mensagemStatus = $('#mensagemStatus');
    const $painelPix = $('#painelPix');
    const $painelCartao = $('#painelCartao');
    const $totalPixDisplay = $('#totalPix');
    const $totalCartaoDisplay = $('#totalCartao');
    const $radioPix = $('#pagamentoPix');
    const $radioCartao = $('#pagamentoCartao');

    // Elementos do Cartão de Crédito
    const $numeroCartao = $('#numeroCartao');
    const $validacaoCartao = $('#validacaoCartao');
    const $parcelasSelect = $('#parcelas');
    const $iconeBandeira = $('#iconeBandeira');

    // --- Funções Auxiliares ---

    // Formatação de moeda (R$)
    const formatCurrency = (value) => {
        return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
    };

    // Esconde todos os painéis de pagamento e limpa mensagens
    const resetPanels = () => {
        $painelPix.addClass('hidden');
        $painelCartao.addClass('hidden');
        $mensagemStatus.removeClass('success error').empty();
        $validacaoCartao.empty();
        $iconeBandeira.empty();
    };

    // --- Lógica de Troca de Painéis (Radio Buttons) ---

    // Função chamada sempre que o método de pagamento muda
    const handlePaymentSwitch = () => {
        resetPanels();

        metodoAtual = $('input[name="metodoPagamento"]:checked').val();

        if (metodoAtual === 'pix') {
            $painelPix.removeClass('hidden');
        } else {
            $painelCartao.removeClass('hidden');
        }

        // Garante que os campos de pagamento estejam 'limpos' no estado inicial
        // Se estiver trocando, recalcula o valor para garantir que o display reflita o estado atual
        calculateTotals();
    };

    // Eventos de mudança nos radios
    $radioPix.on('change', handlePaymentSwitch);
    $radioCartao.on('change', handlePaymentSwitch);


    // --- Lógica de Cálculo de Totais ---

    const calculateTotals = () => {
        // 1. Captura o valor base
        const valorStr = $valorInput.val();
        if (!valorStr || isNaN(parseFloat(valorStr)) || parseFloat(valorStr) <= 0) {
            valorBase = 0;
            $totalPixDisplay.text(formatCurrency(0));
            $totalCartaoDisplay.text(formatCurrency(0));
            return;
        }
        valorBase = parseFloat(valorStr);

        if (metodoAtual === 'pix') {
            // Pix: 10% de desconto
            const totalPix = valorBase * 0.90;
            $totalPixDisplay.text(formatCurrency(totalPix));
            // Para o Pix, o total é fixo até o clique em Pagar

        } else if (metodoAtual === 'cartao') {
            // Cartão: Aplica juros com base na parcela selecionada
            const parcelas = parseInt($parcelasSelect.val());
            let taxaJuros = 0;

            if (parcelas === 4) {
                taxaJuros = 0.05; // 5%
            } else if (parcelas === 5) {
                taxaJuros = 0.10; // 10%
            } 
            // 1 a 3 parcelas (default/sem juros) = taxaJuros = 0

            const totalCartao = valorBase * (1 + taxaJuros);
            $totalCartaoDisplay.text(formatCurrency(totalCartao));
        }
    };

    // Conecta o cálculo ao mudar o valor base OU ao mudar o método de pagamento
    $valorInput.on('input', calculateTotals);
    $parcelasSelect.on('change', calculateTotals);

    // Chama o cálculo inicial para exibir R$ 0.00 se o campo valor estiver vazio
    calculateTotals();


    // --- Evento Principal: Informar Dados ---

    $informarDadosBtn.on('click', function() {
        // 1. Validação de campo valor
        const valor = $valorInput.val();
        if (!valor || parseFloat(valor) <= 0) {
            $mensagemStatus.removeClass('success').addClass('error').text("⚠️ Por favor, preencha o campo 'Valor' com um valor válido.");
            resetPanels(); // Garante que nada apareça se o valor for inválido
            return;
        }

        // Limpa mensagens anteriores
        $mensagemStatus.empty(); 

        // 2. Exibe o painel correspondente ao método atual
        handlePaymentSwitch();

        // 3. Recalcula e atualiza os displays (caso o valor tenha mudado enquanto o painel estava oculto)
        calculateTotals();

        // Se for Pix, o valor já foi atualizado no handlePaymentSwitch
        // Se for Cartão, o valor já foi atualizado pelo evento on('change') do select

        // Garante que o estado visual esteja correto
        const painelExibido = metodoAtual === 'pix' ? $painelPix : $painelCartao;
        painelExibido.removeClass('hidden');

        // Adiciona feedback visual de sucesso no campo principal
        $mensagemStatus.removeClass('error').addClass('success').text(`✅ Dados carregados com sucesso para pagamento via ${metodoAtual.toUpperCase()}.`);
    });

    // --- Lógica do Cartão de Crédito (Validação e Ícones) ---

    $numeroCartao.on('input', function() {
        let value = $(this).val().replace(/\s/g, ''); // Remove espaços
        let formattedValue = '';

        // Formatação automática (XXXX XXXX XXXX XXXX)
        for (let i = 0; i < value.length; i++) {
            if (i > 0 && i % 4 === 0) {
                formattedValue += ' ';
            }
            formattedValue += value[i];
        }
        $(this).val(formattedValue);

        // Limpa validação anterior
        $validacaoCartao.empty();

        const cleanValue = value.replace(/\s/g, '');

        if (cleanValue.length > 0) {
            // 1. Validação de bandeira e ícone
            const firstDigits = cleanValue.substring(0, 4);
            $iconeBandeira.empty(); // Limpa ícones antigos

            if (firstDigits.startsWith("1234")) {
                // Escolha de ícone para Visa/Maestro (Exemplo: um símbolo V)
                $iconeBandeira.html('💳'); 
            } else if (firstDigits.startsWith("4321")) {
                // Escolha de ícone para Mastercard (Exemplo: um símbolo M)
                $iconeBandeira.html('Ⓜ️');
            } else {
                // Cartão inválido
                $validacaoCartao.html("Número de cartão inválido.");
                $(this).removeClass('is-valid').addClass('is-invalid');
            }
        } else {
            // Campo vazio
            $iconeBandeira.empty();
            $(this).removeClass('is-valid is-invalid');
        }

        // Recalcula o total para que o valor seja atualizado conforme a interação no cartão
        if (metodoAtual === 'cartao') {
             calculateTotals();
        }
    });

    // --- Evento de Confirmação de Pagamento ---

    $('#pagarPix').on('click', function() {
        // Em um cenário real, aqui haveria uma chamada de API para gerar o QR Code
        $mensagemStatus.removeClass('error').addClass('success').text("🎉 Pagamento Pix realizado com sucesso! Agradecemos sua compra.");

        // Opcional: limpar a página após sucesso
        // $valorInput.val(''); 
        // resetPanels();
    });

    $('#pagarCartao').on('click', function() {
        // Validações finais antes de processar (Apenas para este exercício)
        const numero = $numeroCartao.val().replace(/\s/g, '');
        const validade = $('#validade').val();
        const cvv = $('#cvv').val();

        if (numero.length < 16 || validade.length !== 5 || cvv.length === 0) {
             $mensagemStatus.removeClass('success').addClass('error').text("❌ Por favor, preencha todos os dados do cartão corretamente.");
             return;
        }

        // Em um cenário real, aqui haveria uma chamada de API para processar o pagamento
        $mensagemStatus.removeClass('error').addClass('success').text("🎉 Pagamento com Cartão de Crédito realizado com sucesso! Sua compra foi aprovada.");

        // Opcional: limpar a página após sucesso
        // $valorInput.val('');
        // resetPanels();
    });

});
```

## 🚀 Como Executar o Projeto

1.  **Crie uma Pasta:** Crie uma nova pasta no seu computador (ex: `PagamentoSite`).
2.  **Crie os Arquivos:** Dentro dessa pasta, crie três arquivos:
    *   `index.html`
    *   `style.css`
    *   `script.js`
3.  **Cole o Código:** Copie e cole o conteúdo correspondente de cada bloco de código nos respectivos arquivos.
4.  **Teste:** Abra o arquivo `index.html` em qualquer navegador moderno (Chrome, Firefox, etc.).

### Resumo do Comportamento Implementado:

*   **Validação de Valor:** Ao clicar em "Informar Dados" com o campo `valor` vazio, aparece o alerta/mensagem de erro.
*   **Troca de Painel:** Ao mudar o rádio, só um painel (`Pix` ou `Cartão`) é exibido, e o outro fica escondido.
*   **Pix:** Ao ser exibido, calcula o total aplicando 10% de desconto sobre o `valorBase`.
*   **Cartão - Ícones:** A função `input` no campo `numeroCartao` verifica se começa com "1234" ou "4321" e insere um ícone correspondente.
*   **Cartão - Validação:** Se o número não iniciar com os padrões, a mensagem de "Número inválido" aparece.
*   **Cartão - Parcelas e Juros:** Ao mudar a seleção de parcelas, o `calculateTotals` é disparado, aplicando 0%, 5% ou 10% de juros no `totalCartao`.
*   **Atualização de Total:** O `totalCartao` se atualiza dinamicamente sempre que o valor base ou a parcela muda.
*   **Botão Pagar:** Ambos os botões de pagar exibem uma mensagem de sucesso padronizada.

Este projeto cumpre todos os requisitos solicitados no enunciado! Boa sorte na sua entrega!

